//! The Linux desktop entry: one `com.paracord.desktop.desktop` that names the
//! app, its icon, its window (`StartupWMClass`, the Wayland app id) and the
//! `paracord://` scheme (`docs/design/index-checkpoints/window-chrome.md`).
//!
//! A package (deb, rpm, AppImage) installs the entry itself
//! (`client/src-tauri/linux/com.paracord.desktop.desktop`, generated by
//! [`main_entry`] and held equal to it by a test). At start the app finds the
//! entry that wins in the XDG data directories and makes it the default for
//! `paracord://`. Only when no entry exists (a bare binary, an AppImage nobody
//! integrated) does the app write one, with its icon, into the user's data
//! directory; it rewrites that one when its program moves, and never touches an
//! entry it did not write. An entry that does not declare the scheme is
//! reported, not patched. The separate `paracord-desktop-handler.desktop` that
//! earlier versions wrote is removed: the scheme lives on the main entry.
//!
//! `Exec=` quoting. `tauri-plugin-deep-link` writes `Exec="/path/app" %u`: the
//! path is always wrapped in double quotes. The Desktop Entry spec allows that,
//! but `xdg-open`'s generic path (the one a desktop without GNOME, KDE or XFCE
//! detection takes: i3, sway, a bare window manager) runs `command -v` on the
//! first word of `Exec=` without unquoting it, finds no file called
//! `"/path/app"` and gives up with "no method available". `gio open` copes,
//! which is why it passed while `xdg-open` did not. So this app writes the
//! entry itself, following the spec's quoting rules exactly: an argument is
//! quoted only when it contains a reserved character, which an ordinary install
//! path never does, and `%u` is the last word.

use std::path::{Path, PathBuf};

use crate::app_identity::{APP_ID, APP_NAME};

/// The entry's file name, the desktop file ID that the window's app id names.
pub fn entry_file_name() -> String {
    format!("{APP_ID}.desktop")
}

/// The handler entry earlier versions wrote next to the main one.
pub const LEGACY_HANDLER_FILE: &str = "paracord-desktop-handler.desktop";

/// Marks an entry this app wrote (and may rewrite).
const GENERATED_MARK: &str = "X-Paracord-Generated=true";

/// Characters that force an `Exec=` argument into double quotes (Desktop Entry
/// Specification, "The Exec key": space, tab, newline, quotes, backslash, and
/// the shell metacharacters it lists).
const RESERVED: &[char] = &[
    ' ', '\t', '\n', '"', '\'', '\\', '>', '<', '~', '|', '&', ';', '$', '*', '?', '#', '(', ')',
    '`',
];

/// One program path as an `Exec=` argument, ready to sit in the file.
///
/// Unquoted when it can be. When quoting is needed, `"`, `` ` ``, `$` and `\`
/// are backslash-escaped inside the quotes, and then every backslash is
/// doubled again, because the file format's own string escaping is applied
/// before the Exec parser sees the value. A literal `%` is written `%%`.
pub fn exec_argument(path: &str) -> String {
    let path = path.replace('%', "%%");
    if !path.contains(RESERVED) {
        return path;
    }
    let mut quoted = String::with_capacity(path.len() + 2);
    quoted.push('"');
    for c in path.chars() {
        match c {
            '"' | '`' | '$' => {
                // Exec-level escape, itself escaped for the file format.
                quoted.push_str("\\\\");
                quoted.push(c);
            }
            // The backslash being escaped is doubled again by the file format.
            '\\' => quoted.push_str("\\\\\\\\"),
            _ => quoted.push(c),
        }
    }
    quoted.push('"');
    quoted
}

/// The whole `Exec=` value: the program, then `%u` (one URL).
pub fn exec_line(program: &Path) -> String {
    format!("{} %u", exec_argument(&program.to_string_lossy()))
}

/// The main entry. `program` is what `Exec=` runs: the bare binary name in the
/// packaged copy, an absolute path when the app writes its own.
pub fn main_entry(program: &Path, schemes: &[&str]) -> String {
    let mimes: String = schemes
        .iter()
        .map(|scheme| format!("x-scheme-handler/{scheme};"))
        .collect();
    format!(
        "[Desktop Entry]\nType=Application\nName={APP_NAME}\nComment=Chat, voice and video with your servers and friends\nExec={exec}\nIcon={APP_ID}\nTerminal=false\nCategories=Network;InstantMessaging;Chat;\nMimeType={mimes}\nStartupWMClass={APP_ID}\n",
        exec = exec_line(program),
    )
}

/// The entry the app writes for itself: the main entry plus the mark that says
/// it may rewrite it.
pub fn generated_entry(program: &Path, schemes: &[&str]) -> String {
    format!("{}{GENERATED_MARK}\n", main_entry(program, schemes))
}

/// The value of `key` in the `[Desktop Entry]` group, if present.
fn entry_value<'a>(entry: &'a str, key: &str) -> Option<&'a str> {
    let mut in_group = false;
    for line in entry.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_group = line == "[Desktop Entry]";
            continue;
        }
        if !in_group {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            if k.trim() == key {
                return Some(v.trim());
            }
        }
    }
    None
}

/// Whether the entry's `MimeType=` list names `x-scheme-handler/<scheme>`.
pub fn declares_scheme(entry: &str, scheme: &str) -> bool {
    let wanted = format!("x-scheme-handler/{scheme}");
    entry_value(entry, "MimeType")
        .is_some_and(|list| list.split(';').any(|mime| mime.trim() == wanted))
}

/// An entry found under an `applications` directory.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FoundEntry {
    pub path: PathBuf,
    /// In the user's data directory (where the app may write).
    pub in_user_dir: bool,
    pub content: String,
}

/// What to do about the desktop entry at start.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Plan {
    /// Someone else's entry (a package, an installer) that declares the
    /// schemes: leave it, make it the default.
    UseExisting(PathBuf),
    /// No entry anywhere, or the app's own entry is out of date: write it.
    Write(PathBuf),
    /// The app's own entry, already as wanted.
    Current(PathBuf),
    /// An entry that is not the app's lacks a scheme: say so, change nothing.
    Refuse(String),
}

/// Decide from the entry that wins in the XDG data directories, if any.
pub fn plan(
    found: Option<&FoundEntry>,
    user_target: &Path,
    wanted: &str,
    schemes: &[&str],
) -> Plan {
    let Some(found) = found else {
        return Plan::Write(user_target.to_path_buf());
    };
    let ours = found.in_user_dir
        && found
            .content
            .lines()
            .any(|line| line.trim() == GENERATED_MARK);
    if ours {
        return if found.content == wanted {
            Plan::Current(found.path.clone())
        } else {
            Plan::Write(found.path.clone())
        };
    }
    let missing: Vec<&str> = schemes
        .iter()
        .copied()
        .filter(|scheme| !declares_scheme(&found.content, scheme))
        .collect();
    if missing.is_empty() {
        Plan::UseExisting(found.path.clone())
    } else {
        Plan::Refuse(format!(
            "{} does not declare MimeType=x-scheme-handler/{}; links will not open this app until it does",
            found.path.display(),
            missing.join(";x-scheme-handler/")
        ))
    }
}

/// The `applications` directories in XDG order: the user's first, then
/// `XDG_DATA_DIRS` (default `/usr/local/share:/usr/share`).
#[cfg(target_os = "linux")]
fn application_dirs(user_data: &Path) -> Vec<(PathBuf, bool)> {
    let mut dirs = vec![(user_data.join("applications"), true)];
    let system = std::env::var("XDG_DATA_DIRS")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "/usr/local/share:/usr/share".to_string());
    for dir in system.split(':').filter(|dir| !dir.is_empty()) {
        dirs.push((Path::new(dir).join("applications"), false));
    }
    dirs
}

/// The icon a written entry names, at the sizes a launcher asks for.
#[cfg(target_os = "linux")]
const ICONS: [(&str, &[u8]); 2] = [
    ("256x256", include_bytes!("../icons/128x128@2x.png")),
    ("512x512", include_bytes!("../icons/icon.png")),
];

/// Put the icon a written entry names into the user's hicolor theme.
#[cfg(target_os = "linux")]
fn install_icons(user_data: &Path) -> Result<bool, String> {
    let theme = user_data.join("icons").join("hicolor");
    let mut changed = false;
    for (size, bytes) in ICONS {
        let dir = theme.join(size).join("apps");
        let target = dir.join(format!("{APP_ID}.png"));
        if std::fs::read(&target).ok().as_deref() == Some(bytes) {
            continue;
        }
        std::fs::create_dir_all(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        std::fs::write(&target, bytes).map_err(|e| format!("{}: {e}", target.display()))?;
        changed = true;
    }
    // A theme directory with a cache is read from the cache alone.
    if changed && theme.join("icon-theme.cache").exists() {
        std::process::Command::new("gtk-update-icon-cache")
            .args(["-f", "-t"])
            .arg(&theme)
            .status()
            .map_err(|e| format!("gtk-update-icon-cache: {e}"))?;
    }
    Ok(changed)
}

/// Find, write or adopt the entry, retire the old handler entry, and make the
/// entry the default for the schemes. Returns a line for the client log.
#[cfg(target_os = "linux")]
pub fn register(app: &tauri::AppHandle, schemes: &[&str]) -> Result<String, String> {
    use std::process::Command;
    use tauri::Manager;

    let bin = tauri::utils::platform::current_exe().map_err(|e| e.to_string())?;
    // An AppImage runs from a temporary mount; the file the owner launched is
    // the one that must be called.
    let program = app.env().appimage.map_or(bin, PathBuf::from);
    let user_data = app.path().data_dir().map_err(|e| e.to_string())?;
    let user_apps = user_data.join("applications");
    let file_name = entry_file_name();

    let mut user_dir_changed = false;
    let legacy = user_apps.join(LEGACY_HANDLER_FILE);
    if legacy.exists() {
        std::fs::remove_file(&legacy).map_err(|e| format!("{}: {e}", legacy.display()))?;
        user_dir_changed = true;
    }

    let found = application_dirs(&user_data)
        .into_iter()
        .map(|(dir, in_user_dir)| (dir.join(&file_name), in_user_dir))
        .find_map(|(path, in_user_dir)| {
            std::fs::read_to_string(&path)
                .ok()
                .map(|content| FoundEntry {
                    path,
                    in_user_dir,
                    content,
                })
        });
    let wanted = generated_entry(&program, schemes);
    let mut outcome = match plan(
        found.as_ref(),
        &user_apps.join(&file_name),
        &wanted,
        schemes,
    ) {
        Plan::Refuse(reason) => return Err(reason),
        Plan::UseExisting(path) => format!("the entry {} (not written by the app)", path.display()),
        Plan::Current(path) => {
            install_icons(&user_data)?;
            format!("the app's entry {}", path.display())
        }
        Plan::Write(path) => {
            std::fs::create_dir_all(&user_apps).map_err(|e| e.to_string())?;
            std::fs::write(&path, &wanted).map_err(|e| format!("{}: {e}", path.display()))?;
            install_icons(&user_data)?;
            user_dir_changed = true;
            format!("the app's entry {}, written now", path.display())
        }
    };
    if user_dir_changed {
        Command::new("update-desktop-database")
            .arg(&user_apps)
            .status()
            .map_err(|e| format!("update-desktop-database: {e}"))?;
    }

    // `xdg-mime default` rewrites mimeapps.list; only when it says otherwise.
    for scheme in schemes {
        let mime = format!("x-scheme-handler/{scheme}");
        let current = Command::new("xdg-mime")
            .args(["query", "default", &mime])
            .output()
            .map_err(|e| format!("xdg-mime: {e}"))?;
        if String::from_utf8_lossy(&current.stdout).trim() != file_name {
            let status = Command::new("xdg-mime")
                .args(["default", &file_name, &mime])
                .status()
                .map_err(|e| format!("xdg-mime: {e}"))?;
            if !status.success() {
                return Err(format!(
                    "xdg-mime default {file_name} {mime} failed: {status}"
                ));
            }
        }
    }
    outcome.insert_str(0, &format!("{} open through ", schemes.join(", ")));
    Ok(outcome)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A reader of `Exec=` that follows the specification, in the two layers
    /// the spec describes: the key-file string escapes first (`\\` is one
    /// backslash), then the argument quoting (`"..."` with backslash-escaped
    /// `"`, `` ` ``, `$`, `\`), then field codes. Unquoted words split on
    /// spaces. This is what `gio`/GLib do.
    fn parse_exec(value: &str) -> Vec<String> {
        let mut unescaped = String::new();
        let mut chars = value.chars();
        while let Some(c) = chars.next() {
            if c == '\\' {
                match chars.next() {
                    Some('\\') => unescaped.push('\\'),
                    Some('s') => unescaped.push(' '),
                    Some('n') => unescaped.push('\n'),
                    Some('t') => unescaped.push('\t'),
                    Some('r') => unescaped.push('\r'),
                    other => panic!("unknown key-file escape \\{other:?}"),
                }
            } else {
                unescaped.push(c);
            }
        }
        let mut words: Vec<String> = Vec::new();
        let mut word = String::new();
        let mut in_word = false;
        let mut quoted = false;
        let mut it = unescaped.chars().peekable();
        while let Some(c) = it.next() {
            if quoted {
                match c {
                    '"' => quoted = false,
                    '\\' => word.push(it.next().expect("dangling escape")),
                    _ => word.push(c),
                }
            } else {
                match c {
                    '"' => {
                        quoted = true;
                        in_word = true;
                    }
                    ' ' => {
                        if in_word {
                            words.push(std::mem::take(&mut word));
                            in_word = false;
                        }
                    }
                    '\\' | '\'' | '`' | '$' | '>' | '<' | '~' | '|' | '&' | ';' | '*' | '?'
                    | '#' | '(' | ')' => panic!("reserved character {c:?} outside quotes"),
                    _ => {
                        word.push(c);
                        in_word = true;
                    }
                }
            }
        }
        assert!(!quoted, "unterminated quote");
        if in_word {
            words.push(word);
        }
        words.into_iter().map(|w| w.replace("%%", "%")).collect()
    }

    fn exec_of(entry: &str) -> &str {
        entry
            .lines()
            .find_map(|line| line.strip_prefix("Exec="))
            .expect("an Exec line")
    }

    #[test]
    fn an_ordinary_path_is_not_quoted_so_xdg_open_can_find_it() {
        let entry = generated_entry(Path::new("/opt/paracord/paracord-desktop"), &["paracord"]);
        let exec = exec_of(&entry);
        assert_eq!(exec, "/opt/paracord/paracord-desktop %u");
        // The first word is what `xdg-open` runs `command -v` on: no quotes.
        assert!(!exec.split(' ').next().unwrap().contains('"'));
    }

    #[test]
    fn the_exec_line_parses_to_the_program_and_one_url_field() {
        for program in [
            "/opt/paracord/paracord-desktop",
            "/home/a b/Applications/Paracord.AppImage",
            "/home/me/it's here/paracord",
            "/home/me/say \"hi\"/paracord",
            "/home/me/$HOME/`x`/paracord",
            "/home/me/back\\slash/paracord",
            "/home/me/100%/paracord",
        ] {
            let entry = generated_entry(Path::new(program), &["paracord"]);
            assert_eq!(
                parse_exec(exec_of(&entry)),
                vec![program.to_string(), "%u".to_string()],
                "Exec line was {}",
                exec_of(&entry)
            );
        }
    }

    #[test]
    fn only_a_path_that_needs_quotes_gets_them() {
        assert_eq!(exec_argument("/usr/bin/paracord"), "/usr/bin/paracord");
        assert_eq!(exec_argument("/a b/c"), "\"/a b/c\"");
    }

    #[test]
    fn the_main_entry_names_the_app_id_its_icon_its_window_and_the_scheme() {
        let entry = main_entry(Path::new("/usr/bin/paracord-desktop"), &["paracord"]);
        assert!(entry.starts_with("[Desktop Entry]\n"));
        assert_eq!(entry_value(&entry, "Name"), Some("Paracord"));
        assert_eq!(entry_value(&entry, "Icon"), Some(APP_ID));
        assert_eq!(entry_value(&entry, "StartupWMClass"), Some(APP_ID));
        assert_eq!(
            entry_value(&entry, "MimeType"),
            Some("x-scheme-handler/paracord;")
        );
        assert!(declares_scheme(&entry, "paracord"));
        // It is the launcher now: shown in menus.
        assert_eq!(entry_value(&entry, "NoDisplay"), None);
        assert_eq!(entry_value(&entry, "Terminal"), Some("false"));
        assert_eq!(entry_file_name(), "com.paracord.desktop.desktop");
    }

    #[test]
    fn the_packaged_entry_is_the_main_entry_for_the_installed_binary() {
        // deb, rpm and AppImage install this file (tauri.conf.json bundle.linux);
        // it must never drift from what the app would write.
        assert_eq!(
            include_str!("../linux/com.paracord.desktop.desktop"),
            main_entry(Path::new("paracord-desktop"), &["paracord"])
        );
    }

    #[test]
    fn a_scheme_is_read_from_the_desktop_entry_group_only() {
        let entry = "[Desktop Entry]\nMimeType=text/plain; x-scheme-handler/paracord\n[Desktop Action x]\nMimeType=x-scheme-handler/other;\n";
        assert!(declares_scheme(entry, "paracord"));
        assert!(!declares_scheme(entry, "other"));
        assert!(!declares_scheme(
            "[Desktop Entry]\nName=Paracord\n",
            "paracord"
        ));
    }

    fn found(path: &str, in_user_dir: bool, content: &str) -> FoundEntry {
        FoundEntry {
            path: PathBuf::from(path),
            in_user_dir,
            content: content.to_string(),
        }
    }

    #[test]
    fn with_no_entry_anywhere_the_app_writes_its_own() {
        let target = Path::new("/home/me/.local/share/applications/com.paracord.desktop.desktop");
        let wanted = generated_entry(Path::new("/opt/p/paracord-desktop"), &["paracord"]);
        assert_eq!(
            plan(None, target, &wanted, &["paracord"]),
            Plan::Write(target.to_path_buf())
        );
    }

    #[test]
    fn a_packaged_or_installer_entry_is_used_and_never_rewritten() {
        let target = Path::new("/home/me/.local/share/applications/com.paracord.desktop.desktop");
        let wanted = generated_entry(Path::new("/opt/p/paracord-desktop"), &["paracord"]);
        let packaged = main_entry(Path::new("paracord-desktop"), &["paracord"]);
        let system = found(
            "/usr/share/applications/com.paracord.desktop.desktop",
            false,
            &packaged,
        );
        assert_eq!(
            plan(Some(&system), target, &wanted, &["paracord"]),
            Plan::UseExisting(system.path.clone())
        );
        // An installer's entry in the user's directory, without the app's mark.
        let user = found(target.to_str().unwrap(), true, &packaged);
        assert_eq!(
            plan(Some(&user), target, &wanted, &["paracord"]),
            Plan::UseExisting(user.path)
        );
    }

    #[test]
    fn an_entry_without_the_scheme_is_reported_not_patched() {
        let target = Path::new("/home/me/.local/share/applications/com.paracord.desktop.desktop");
        let wanted = generated_entry(Path::new("/opt/p/paracord-desktop"), &["paracord"]);
        let bare = found(
            target.to_str().unwrap(),
            true,
            "[Desktop Entry]\nName=Paracord\nExec=/x\n",
        );
        match plan(Some(&bare), target, &wanted, &["paracord"]) {
            Plan::Refuse(reason) => {
                assert!(reason.contains("x-scheme-handler/paracord"), "{reason}")
            }
            other => panic!("expected a refusal, got {other:?}"),
        }
    }

    #[test]
    fn the_apps_own_entry_is_rewritten_when_its_program_moves() {
        let target = Path::new("/home/me/.local/share/applications/com.paracord.desktop.desktop");
        let wanted = generated_entry(Path::new("/home/me/Apps/Paracord.AppImage"), &["paracord"]);
        let before = generated_entry(
            Path::new("/home/me/Downloads/Paracord.AppImage"),
            &["paracord"],
        );
        let ours = found(target.to_str().unwrap(), true, &before);
        assert_eq!(
            plan(Some(&ours), target, &wanted, &["paracord"]),
            Plan::Write(ours.path.clone())
        );
        let current = found(target.to_str().unwrap(), true, &wanted);
        assert_eq!(
            plan(Some(&current), target, &wanted, &["paracord"]),
            Plan::Current(current.path)
        );
    }
}
